  : originalFilename;

const thaiMonths = ["มกราคม","กุมภาพันธ์","มีนาคม","เมษายน","พฤษภาคม","มิถุนายน","กรกฎาคม","สิงหาคม","กันยายน","ตุลาคม","พฤศจิกายน","ธันวาคม"];

let date = null;
let date_p = null;
let thaiMonthYear = null;

const match = originalFilename.match(/_(\d{4})(\d{2})(\d{2})_/);
if (match) {
  const [, year, month, day] = match;
  const d = new Date(Date.UTC(Number(year), Number(month) - 1, Number(day)));
  // d.setUTCDate(d.getUTCDate() - 1);

  const dd = String(d.getUTCDate()).padStart(2, '0');
  const mm = String(d.getUTCMonth() + 1).padStart(2, '0');
  const yyyy = d.getUTCFullYear();

  date = `${dd}/${mm}/${yyyy}`;
  date_p = `${mm}/${dd}/${yyyy}`;
  thaiMonthYear = `${thaiMonths[d.getUTCMonth()]} ${yyyy + 543}`;
}

return [{
  json: {
    source_file_id,
    originalFilename,
    fileExtension,
    base_name,
    template_id: "12EEsx1wg8HYRzoOCgaOnI7reuF6nN4ZZCs5Fz75BqEM",
    processing_folder_id: "1GwBRbMYCBgspVwrIhJDDsnXx6FOVXTh7",
    output_folder_id: "1FLRJunykKBc5OvbZAUmTR3FvAOclRPrT",
    trash_folder_id: "1rHWght9L7HAu1bhF1B-HnJH0O53nuqcw",
