const sheet1 = $('Read Sheet 1').all(0, $runIndex);
const sheet2 = $input.all();

const normalize = (v) =>
  (v === undefined || v === null) ? '' : String(v).trim().replace(/-/g, '/');

const set = new Set();
for (const it of sheet1) {
  const c = normalize(it.json?.['เครื่องจักร']);
  if (c) set.add(c);
}
for (const it of sheet2) {
  const c = normalize(it.json?.['เครื่อง']);
  if (c) set.add(c);
}

return [{ json: { machine: [...set] }, pairedItem: { item: 0 } }];

const file = $('File Payload').first(0, $runIndex);
const binary = file.binary || {};

let machine = [];
try {
  machine = $('Combine Machines').first(0, $runIndex).json.machine || [];
} catch (e) {}

const normalize = (v) =>
  (v === undefined || v === null) ? '' : String(v).trim().replace(/-/g, '/');

const machineSet = new Set(machine.map(normalize));
const sheet3 = $input.all();

const MACHINE_COL = 'Machine';
const NAME_COL = 'Full_name';
const SEP = ' | ';
const chosen = new Map();

for (const it of sheet3) {
  if (!machineSet.has(normalize(it.json?.[MACHINE_COL]))) continue;
  const raw = it.json?.[NAME_COL];
  if (raw === undefined || raw === null || String(raw).trim() === '') continue;

  const parts = String(raw).split('|').map(p => p.trim()).slice(0, 4);
  const trimmed = parts.join(SEP);
  const front = parts.slice(0, 3).join(SEP);
  const color = parts[3] || '';
  const isSai = color.endsWith('ใส');

  if (!chosen.has(front) || (!chosen.get(front).isSai && isSai)) {
    chosen.set(front, { trimmed, isSai });
  }
}

const produce_name = [...chosen.values()].map(v => v.trimmed);

return [{
  json: {
    machine,
    produce_name,
    state: {
      file: file.json,
      ocr: {}
    }
  },
  ...(Object.keys(binary).length ? { binary } : {})
}];

