const anchor = $('OCR 1 Input').item;
const binary = anchor.binary || {};
const prev = anchor.json || {};

function parseGemini(j) {
  const raw = j?.candidates?.[0]?.content?.parts?.[0]?.text;
  if (!raw || typeof raw !== 'string') {
    return { ok:false, result:[], error:j?.error?.message || j?.message || 'No Gemini candidate text' };
  }
  try {
    const match = raw.match(/```json\s*([\s\S]*?)\s*```/i);
    const clean = (match?.[1] ?? raw).trim()
      .replace(/^```(?:json)?/i, '')
      .replace(/```$/i, '')
      .trim();
    const parsed = JSON.parse(clean);
    let rows = [];
    if (Array.isArray(parsed)) rows = parsed;
    else if (parsed && Array.isArray(parsed.output)) rows = parsed.output;
    else if (parsed && typeof parsed === 'object') {
      rows = Object.entries(parsed).map(([key,value]) => {
        if (value && typeof value === 'object' && !Array.isArray(value)) {
          return value.row ? value : { ...value, row_id:value.row_id ?? key };
        }
        return { row_id:key, value };
      });
    }
    return { ok:rows.length > 0, result:rows, error:rows.length ? null : 'Parsed JSON contains no rows' };
  } catch (e) {
    return { ok:false, result:[], error:`JSON parse failed: ${e.message}` };
  }
}

const parsed = parseGemini(input.json || {});
