const data=query.json||{};
const rows=Array.isArray(data.result)?data.result:[];
const state=data.state||{file:{},ocr:{}};
const binary=query.binary||{};
const sheetData=$input.first()?.json||{};

const productFields=[];
for(const [key,val] of Object.entries(sheetData)){
  if(key.startsWith('ชื่อสินค้า#')&&val) productFields.push(val);
}
function cleanValue(value){
  if(typeof value==='string'){
    const x=value.trim().toLowerCase();
    if(x==='null'||x==='-'||x==='0') return null;
  }
  return value;
}
function findMatch(keyword){
  if(!keyword||!productFields.length) return null;
  return productFields.find(v=>String(v).includes(String(keyword).trim()))||null;
}

return rows.filter(r=>r&&r.row).sort((a,b)=>a.row-b.row).map(r=>{
