 const d=getData(name),m=d.usageMetadata; if(!m) continue;
 const raw=d.modelVersion||'default'; let key='default',rate=pricing.default;
 for(const k of Object.keys(pricing)){if(k!=='default'&&raw.includes(k)){key=k;rate=pricing[k];break;}}
 const inn=m.promptTokenCount||0,out=(m.candidatesTokenCount||0)+(m.thoughtsTokenCount||0);
 const usd=inn*(rate.input/1e6)+out*(rate.output/1e6);
 totalIn+=inn; totalOut+=out; totalUsd+=usd;
 if(!byModel[key]) byModel[key]={total_tokens:0,cost_usd:0};
 byModel[key].total_tokens+=inn+out; byModel[key].cost_usd+=usd;
}
for(const k of Object.keys(byModel)){
 const usd=byModel[k].cost_usd; byModel[k].cost_thb=(usd*33).toFixed(4)+' บาท'; byModel[k].cost_usd=usd.toFixed(6);
}
return [{json:{summary:{total_tokens_used:totalIn+totalOut,tokens_breakdown:{input:totalIn,output_including_thoughts:totalOut},
